#!/bin/sh
# Generated by build_ports_setup.py. Copy this ONE file to share/roms/ports.
# Embedded feature installers and separate Ports actions. No downloads or private state.
exec python3 -c 'import base64,io,subprocess,sys,tempfile,zipfile
with tempfile.TemporaryDirectory(prefix="art-book-setup-") as folder:
    zipfile.ZipFile(io.BytesIO(base64.b64decode(""))).extractall(folder)
    legacy = "--legacy-setup" in sys.argv[1:]
    args = [a for a in sys.argv[1:] if a != "--legacy-setup"]
    entry = "/ports_setup.py" if legacy or any(a == "--playtime" or a == "--startup" or a.startswith("--startup=") for a in args) else "/ports_actions.py"
    sys.exit(subprocess.call([sys.executable,folder+entry,*args]))
' "$@"
